/* @lc app=leetcode id=3757 lang=kotlin */ class Solution { fun countEffective(nums: IntArray): Int = 1_000_000_007L.let { M -> nums.size.let { n -> IntArray(1 shl 20).also { c -> nums.forEach { c[it]++ } }.also { c -> (0 until 20).forEach { b -> c.indices.forEach { m -> if (m shr b and 1 == 1) c[m] += c[m xor (1 shl b)] } } }.let { cnt -> LongArray(n + 1).also { pw -> pw[0] = 1L }.also { pw -> (1..n).forEach { pw[it] = pw[it - 1] * 2 % M } }.let { pw -> nums.fold(0) { a, b -> a or b }.let { tot -> ((generateSequence(tot) { if (it == 0) null else (it - 1) and tot }.filter { it != 0 }.sumOf { B -> (if (Integer.bitCount(B) % 2 == 1) 1L else -1L) * pw[cnt[(1 shl 20) - 1 xor B]] } % M + M) % M).toInt() } } } } } }